changeSet.sql:
CREATE TABLE cbs_refresh_run ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, facility_id BIGINT NOT NULL, as_of_date DATE NOT NULL, status VARCHAR(30) NOT NULL, triggered_by VARCHAR(255), started_at TIMESTAMP NOT NULL, finished_at TIMESTAMP, patients_processed INTEGER, events_created INTEGER, findings_active INTEGER, findings_new INTEGER, findings_cleared INTEGER, error_message TEXT ); CREATE INDEX idx_cbs_refresh_run_facility ON cbs_refresh_run (facility_id, started_at DESC);
CREATE TABLE cbs_patient_summary ( facility_id BIGINT NOT NULL, person_uuid VARCHAR(255) NOT NULL, patient_id VARCHAR(255), hospital_number VARCHAR(255), sex VARCHAR(50), date_of_birth DATE, treatment_status VARCHAR(50), treatment_status_date DATE, vital_status VARCHAR(50), latest_event_type VARCHAR(50), latest_event_date DATE, open_flags INTEGER NOT NULL DEFAULT 0, open_gaps INTEGER NOT NULL DEFAULT 0, status_discrepancy BOOLEAN NOT NULL DEFAULT FALSE, as_of_date DATE NOT NULL, run_id BIGINT NOT NULL, CONSTRAINT pk_cbs_patient_summary PRIMARY KEY (facility_id, person_uuid) ); CREATE INDEX idx_cbs_patient_summary_ids ON cbs_patient_summary (facility_id, patient_id, hospital_number);
CREATE TABLE cbs_finding ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, facility_id BIGINT NOT NULL, person_uuid VARCHAR(255) NOT NULL, rule_code VARCHAR(30) NOT NULL, rule_version INTEGER NOT NULL, category VARCHAR(100) NOT NULL, finding_type VARCHAR(50) NOT NULL, severity VARCHAR(20) NOT NULL, event_type VARCHAR(50), description TEXT NOT NULL, evidence JSONB, dedup_key VARCHAR(500) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, first_detected_at TIMESTAMP NOT NULL, last_detected_at TIMESTAMP NOT NULL, cleared_at TIMESTAMP, CONSTRAINT uq_cbs_finding_dedup UNIQUE (facility_id, dedup_key) ); CREATE INDEX idx_cbs_finding_person ON cbs_finding (facility_id, person_uuid); CREATE INDEX idx_cbs_finding_active ON cbs_finding (facility_id, active);
CREATE TABLE cbs_issue ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, finding_id BIGINT NOT NULL REFERENCES cbs_finding (id), facility_id BIGINT NOT NULL, person_uuid VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL, assigned_to VARCHAR(255), due_date DATE, escalated BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, resolved_at TIMESTAMP, CONSTRAINT uq_cbs_issue_finding UNIQUE (finding_id) ); CREATE INDEX idx_cbs_issue_facility ON cbs_issue (facility_id, status);
-- Append-only. Nothing in the code updates or deletes rows here. CREATE TABLE cbs_issue_history ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, issue_id BIGINT NOT NULL REFERENCES cbs_issue (id), action VARCHAR(50) NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30), note TEXT, action_date DATE, details JSONB, performed_by VARCHAR(255) NOT NULL, performed_at TIMESTAMP NOT NULL ); CREATE INDEX idx_cbs_issue_history_issue ON cbs_issue_history (issue_id, performed_at);
CREATE TABLE cbs_audit_log ( id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, facility_id BIGINT, action VARCHAR(50) NOT NULL, reference VARCHAR(255), details JSONB, performed_by VARCHAR(255) NOT NULL, performed_at TIMESTAMP NOT NULL );
CREATE TABLE cbs_setting ( setting_key VARCHAR(100) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL, description TEXT );
